def main():
 e=R/'effective-main-comparison';selection=read(R/'effective-main-selection.json');summary=read(e/'summary.json')['rows'];memory=read(e/'memory-option-peaks.json');campaign=read(R/'campaign-totals.json');assert len(summary)==len(memory)==10 and campaign['recorded_actual_episode_trials']==229
